/**
 * SE39 — acceptance gate: a transcript generated by our writer PARSES through the REAL
 * `claude-code-log` Pydantic parser, with zero dangling tool_use. Gated on the presence of the
 * cloned parser + python3 + pydantic (skips cleanly in CI where the study clone is absent). This is
 * the DoD's "parses through a real ecosystem parser" evidence — locked where the tooling exists.
 */
import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterAll, describe, expect, it } from "vitest";

import { claudeCodeRecords } from "../../src/internal/persistence/claude-code-transcript.js";
import type { ConversationStep } from "../../src/types/conversation.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO = join(__dirname, "..", "..", "..", "..");
const CLONE = join(REPO, "knowledge-base", "references", "claude-code-log");
const VALIDATOR = join(__dirname, "_helpers", "validate_claude_code_jsonl.py");

function pythonReady(): boolean {
  if (!existsSync(join(CLONE, "claude_code_log", "models.py"))) return false;
  try {
    execFileSync("python3", ["-c", "import pydantic"], { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
}

const ready = pythonReady();
let work: string | undefined;
afterAll(() => {
  if (work) rmSync(work, { recursive: true, force: true });
});

describe.skipIf(!ready)("SE39 — round-trip through the real claude-code-log parser", () => {
  it("a tool-calling transcript parses with zero dangling tool_use", () => {
    const steps: ConversationStep[] = [
      { type: "thinkingMessage", message: { text: "multiply then add", thinkingDurationMs: 30 } },
      { type: "assistantMessage", message: { text: "Computing." } },
      {
        type: "toolCall",
        message: { callId: "toolu_1", name: "calculator", args: { a: 17, b: 23, op: "mul" } },
      },
      {
        type: "toolResult",
        message: { callId: "toolu_1", name: "calculator", result: "391", isError: false },
      },
      {
        type: "toolCall",
        message: { callId: "toolu_2", name: "calculator", args: { a: 391, b: 5, op: "add" } },
      },
      {
        type: "toolResult",
        message: { callId: "toolu_2", name: "calculator", result: "396", isError: false },
      },
      { type: "assistantMessage", message: { text: "The answer is 396." } },
    ];
    const recs = claudeCodeRecords(steps, {
      userMessage: "Compute 17*23 then +5 using the calculator.",
      cwd: "/home/u/proj",
      sessionId: "se39-rt",
      model: "openai/gpt-4o-mini",
      version: "1.0.0-theokit",
      timestamp: "2026-07-15T12:00:00.000Z",
    });

    work = mkdtempSync(join(tmpdir(), "se39-rt-"));
    const jsonl = join(work, "se39-rt.jsonl");
    writeFileSync(jsonl, `${recs.map((r) => JSON.stringify(r)).join("\n")}\n`);

    const out = execFileSync("python3", [VALIDATOR, CLONE, jsonl], { encoding: "utf8" }).trim();
    // e.g. "OK 5 records, 2 tool pairs"
    expect(out).toMatch(/^OK \d+ records, 2 tool pairs$/);
  });
});
